    wire w2 = a & c;
    wire w3 = a & d;
    wire w4 = b & c;
    wire w5 = b & d;
    wire w6 = c & d;
    wire w7 = ~(w1 | w2 | w3 | w4 | w5 | w6);
    wire w8 = ~(a & b & c);
    wire w9 = ~(a & b & d);
    wire w10 = ~(a & c & d);
    wire w11 = ~(b & c & d);
    wire w12 = ~(w8 | w9 | w10 | w11);
    assign q = w7 | w12;
endmodule

